def zigzag_walk(rows, cols):
    result = []
    for r in range(rows):
        if r % 2 == 0:
            cols_range = range(cols)
        else:
            cols_range = range(cols - 1, -1, -1)
        for c in cols_range:
            result.append((r, c))
    return result
